SEVERITY_SCORE = {"high": "8.0", "medium": "5.5", "low": "3.0", "info": "1.0"}      # GitHub's `security-severity`: >=7 high, 4-6.9 medium, <4 low
SARIF_LEVEL = {"high": "error", "medium": "warning", "low": "note", "info": "note"}


def describe(code: str, fallback_title: str = "") -> tuple[str, str, tuple]:
    """(name, advice, CWEs) for a finding code. An unknown code (it should not happen: a test checks) falls back to its own title."""
    return RULES.get(code, (fallback_title or code, "", ()))
